\begin{tikzpicture}[x=0.48cm,y=0.48cm,line cap=round,line join=round,font=\small]
  % Shape P: 2-by-4
  \draw[line width=1.0pt,fill=blue!8] (0,0) grid (4,2);
  \draw[line width=1.05pt] (0,0) rectangle (4,2);
  \node[below] at (2,-0.55){Shape $P$};
  % Shape Q: L from same 8 squares
  \begin{scope}[xshift=7.2cm]
    \fill[orange!12] (0,0) rectangle (3,2);
    \fill[orange!12] (0,2) rectangle (1,4);
    \draw[step=1,line width=0.7pt,gray!65] (0,0) grid (3,2);
    \draw[step=1,line width=0.7pt,gray!65] (0,2) grid (1,4);
    \draw[line width=1.05pt] (0,0)--(3,0)--(3,2)--(1,2)--(1,4)--(0,4)--cycle;
    \node[below] at (1.5,-0.55){Shape $Q$};
  \end{scope}
  \node[align=center] at (5.2,-1.6){Both shapes use the same $8$ unit squares.};
\end{tikzpicture}
